// F6-T1a: PC.texgen (CTO C-3.2; plan section 5.1): sizes, value ranges, tileability, determinism, the pixel cache and
// the generation time.
import test from 'node:test';
import assert from 'node:assert/strict';
import { loadCore } from '../helpers/load.mjs';

const PC = loadCore(), T = PC.texgen, COLOUR = ['grass', 'paving', 'tiles', 'meadow'];
// Pixel hashes at 512 (blob at 64): change only with a data/textures.js change (Designer), regenerated by printing them.
const GOLD = { grass: '7723e46b', paving: '143c00e9', tiles: '51934bf1', meadow: '1c8ed45f' };

test('sizes, RGBA layout, grey colour kinds with alpha 255, value ranges within the spec; blob = radial alpha with RGB 0', () => {
  for (const kind of COLOUR) for (const size of [256, 512]) {
    const t = T.make(kind, size), S = PC.data.textures[kind];
    assert.deepEqual([t.w, t.h, t.data.length], [size, size, size * size * 4], kind);
    let mn = 255, mx = 0, sum = 0;
    for (let i = 0; i < t.data.length; i += 4) {
      assert.ok(t.data[i] === t.data[i + 1] && t.data[i] === t.data[i + 2] && t.data[i + 3] === 255, `${kind} grey, opaque`);
      mn = Math.min(mn, t.data[i]); mx = Math.max(mx, t.data[i]); sum += t.data[i];
    }
    const mean = sum / (size * size) / 255;
    assert.ok(Math.abs(mean - S.base) < 0.06, `${kind} ${size}: mean ${mean.toFixed(3)} near base ${S.base}`);
    assert.ok(mn / 255 > S.base * 0.55 && mx > mn + 10, `${kind} ${size}: range ${mn}..${mx} (detail, not a colour)`);
  }
  const b = T.make('blob', 64), a = (x, y) => b.data[(y * 64 + x) * 4 + 3];
  assert.ok(a(32, 32) > 240 && a(0, 0) === 0 && a(63, 32) < 10, 'opaque centre, clear rim');
  for (let i = 0; i < b.data.length; i += 4) assert.ok(b.data[i] === 0 && b.data[i + 1] === 0 && b.data[i + 2] === 0);
  for (let x = 33; x < 63; x++) assert.ok(a(x, 32) <= a(x - 1, 32), 'alpha falls off outwards');
});

test('tileable: the wrap seam (last row / column -> first) is no larger a step than the largest step inside the texture', () => {
  for (const kind of COLOUR) {
    const t = T.make(kind, 256), n = 256, v = (x, y) => t.data[(y * n + x) * 4];
    let inner = 0, seam = 0;
    for (let y = 0; y < n; y++) for (let x = 0; x < n - 1; x++) inner = Math.max(inner, Math.abs(v(x + 1, y) - v(x, y)), Math.abs(v(y, x + 1) - v(y, x)));
    for (let k = 0; k < n; k++) seam = Math.max(seam, Math.abs(v(0, k) - v(n - 1, k)), Math.abs(v(k, 0) - v(k, n - 1)));
    assert.ok(seam <= inner, `${kind}: seam step ${seam} <= inner step ${inner}`);
    // and the low-frequency part continues: the mean over the first and the last 4 columns agree like neighbours do
    const col = (x) => { let s = 0; for (let y = 0; y < n; y++) s += v(x, y); return s / n; };
    assert.ok(Math.abs(col(0) - col(n - 1)) <= Math.max(...Array.from({ length: n - 1 }, (_, x) => Math.abs(col(x + 1) - col(x)))) + 1e-9, kind + ' column means');
  }
});

test('deterministic (pixel hash goldens), a different seed differs, get() caches per kind and size and counts generations', () => {
  for (const kind of COLOUR) {
    assert.equal(T.hash(T.make(kind, 512)), GOLD[kind], kind);
    assert.equal(T.hash(T.make(kind, 512)), T.hash(T.make(kind, 512)), kind + ' repeatable');
    assert.notEqual(T.hash(T.make(kind, 512, undefined, 7)), GOLD[kind], kind + ' seeded');
  }
  const g0 = T.generated, a = T.get('grass', 256), b = T.get('grass', 256);
  assert.equal(a, b); assert.equal(T.generated, g0 + 1);
  T.get('grass', 512); assert.equal(T.generated, g0 + 2);
  assert.throws(() => T.make('marble', 64), /unknown kind/);
});

test('generation time: all MVP textures (4 colour kinds at 512 + blob at 64) in <= 150 ms, best of 3 (CTO C-3.2)', () => {
  const t = [];
  for (let k = 0; k < 3; k++) { const t0 = performance.now(); for (const kind of COLOUR) T.make(kind, 512); T.make('blob', 64); t.push(performance.now() - t0); }
  assert.ok(Math.min(...t) <= 150, `best ${Math.min(...t).toFixed(1)} ms`);
});
